// Task 17-b — splices the 16 new EXPECTED entries (l13-p5..p8 … l16-p5..p8)
// into src/lib/curriculum/expected.ts, replicating gen-expected.ts formatting
// exactly (same normalizeCell rounding, same JSON.stringify(…, null, 2)).
// READ-ONLY against the DB: runs each new solution, never writes, never resets.
import { readFileSync, writeFileSync } from "node:fs";
import { PrismaClient } from "@prisma/client";

const FILE = "src/lib/curriculum/expected.ts";
const BANNER =
  "// AUTO-GENERATED by scripts/gen-expected.ts — do not edit by hand.\n// Grading targets: each problem's solution executed on the seed database.\n\nexport const EXPECTED: Record<string, { columns: string[]; rows: Array<Array<string | number | null>> }> = ";

function normCell(v: unknown): string | number | null {
  if (v === null || v === undefined) return null;
  if (typeof v === "bigint") return Number(v);
  if (typeof v === "number") return Math.round(v * 100) / 100;
  return String(v);
}

const SOL: Record<string, string> = {
  "l13-p5": "SELECT c.name\nFROM customers c\nLEFT JOIN orders o\n       ON o.customer_id = c.id\n      AND o.status = 'cancelled'\nWHERE c.active = 1\n  AND o.id IS NULL\nORDER BY c.name;",
  "l13-p6": "SELECT c.name, c.email, c.city\nFROM customers c\nLEFT JOIN orders o\n       ON o.customer_id = c.id\n      AND o.status = 'delivered'\nWHERE o.id IS NULL\nORDER BY c.name;",
  "l13-p7": "SELECT c.name\nFROM customers c\nLEFT JOIN orders o\n       ON o.customer_id = c.id\n      AND o.status IN ('pending', 'shipped')\nWHERE o.id IS NULL\nORDER BY c.name;",
  "l13-p8": "SELECT c.name\nFROM customers c\nLEFT JOIN orders o\n       ON o.customer_id = c.id\n      AND o.status <> 'delivered'\nWHERE o.id IS NULL\nORDER BY c.name;",
  "l14-p5": "SELECT c1.name AS pair_a, c2.name AS pair_b, c1.region\nFROM customers c1\nJOIN customers c2\n     ON  c1.region = c2.region\n     AND c1.id < c2.id\nWHERE c1.active = 1\n  AND c2.active = 1\nORDER BY c1.region, pair_a, pair_b;",
  "l14-p6": "SELECT o1.id AS first_id, o2.id AS second_id, o1.customer_id\nFROM orders o1\nJOIN orders o2\n     ON  o1.customer_id = o2.customer_id\n     AND o1.id < o2.id\n     AND SUBSTR(o1.created_at, 1, 7) = SUBSTR(o2.created_at, 1, 7)\nORDER BY first_id, second_id;",
  "l14-p7": "SELECT p1.name AS twin_a, p2.name AS twin_b, p1.price AS price\nFROM products p1\nJOIN products p2\n     ON  p1.category = p2.category\n     AND p1.id < p2.id\n     AND ABS(p1.price - p2.price) < 15\nORDER BY price, twin_a;",
  "l14-p8": "SELECT COUNT(*) AS trios\nFROM customers c1\nJOIN customers c2\n     ON  c1.region = c2.region\n     AND c1.id < c2.id\nJOIN customers c3\n     ON  c3.region = c2.region\n     AND c2.id < c3.id;",
  "l15-p5": "SELECT c.name, ROUND(AVG(o.total), 2) AS avg_order\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nGROUP BY c.id\nORDER BY avg_order DESC, name ASC\nLIMIT 5;",
  "l15-p6": "SELECT p.category,\n       ROUND(MIN(p.price), 2) AS min_price,\n       ROUND(MAX(p.price), 2) AS max_price\nFROM products p\nGROUP BY p.category\nORDER BY p.category;",
  "l15-p7": "SELECT c.name, COUNT(o.id) AS orders\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nGROUP BY c.id\nHAVING COUNT(o.id) >= 14\nORDER BY orders DESC, name;",
  "l15-p8": "SELECT s.name,\n       COUNT(*) AS products,\n       SUM(p.stock) AS total_stock,\n       ROUND(AVG(p.price), 2) AS avg_price\nFROM suppliers s\nJOIN products p ON p.supplier_id = s.id\nGROUP BY s.id\nHAVING COUNT(*) >= 3\nORDER BY total_stock DESC, s.name;",
  "l16-p5": "SELECT (SELECT ROUND(SUM(total), 2) FROM orders) AS honest,\n       (SELECT ROUND(SUM(o.total), 2)\n        FROM orders o\n        JOIN order_items oi ON oi.order_id = o.id) AS inflated,\n       ROUND((SELECT SUM(o.total)\n              FROM orders o\n              JOIN order_items oi ON oi.order_id = o.id) /\n             (SELECT SUM(total) FROM orders), 2) AS ratio;",
  "l16-p6": "SELECT COUNT(*) AS rows_joined,\n       COUNT(DISTINCT o.id) AS orders_distinct,\n       COUNT(DISTINCT o.total) AS totals_distinct\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id;",
  "l16-p7": "SELECT (SELECT ROUND(AVG(total), 2) FROM orders) AS honest_avg,\n       (SELECT ROUND(AVG(o.total), 2)\n        FROM orders o\n        JOIN order_items oi ON oi.order_id = o.id) AS inflated_avg;",
  "l16-p8": "SELECT COUNT(*) AS mismatches\nFROM (\n  SELECT o.id\n  FROM orders o\n  JOIN order_items oi ON oi.order_id = o.id\n  GROUP BY o.id\n  HAVING ROUND(SUM(oi.quantity * oi.unit_price), 2) <> ROUND(o.total, 2)\n) aud;",
};

const ANCHORS: Record<string, string> = {
  l13: "l13-p4",
  l14: "l14-p4",
  l15: "l15-p4",
  l16: "l16-p4",
};

async function main() {
  const src = readFileSync(FILE, "utf8");
  const start = src.indexOf("{", src.indexOf("= {"));
  const end = src.lastIndexOf("}");
  const parsed = JSON.parse(src.slice(start, end + 1)) as Record<
    string,
    { columns: string[]; rows: Array<Array<string | number | null>> }
  >;

  const db = new PrismaClient();
  const fresh: Record<string, { columns: string[]; rows: Array<Array<string | number | null>> }> = {};
  for (const [id, sql] of Object.entries(SOL)) {
    const raw = (await db.$queryRawUnsafe(sql)) as Array<Record<string, unknown>>;
    const columns = raw.length ? Object.keys(raw[0]) : [];
    const rows = raw.map((r) => columns.map((c) => normCell(r[c])));
    fresh[id] = { columns, rows };
    console.log(`ran ${id}: ${rows.length} rows, cols=${columns.join("/")}`);
  }
  await db.$disconnect();

  const out: typeof parsed = {};
  for (const key of Object.keys(parsed)) {
    out[key] = parsed[key];
    for (const [lesson, anchor] of Object.entries(ANCHORS)) {
      if (key === anchor) {
        for (let i = 5; i <= 8; i++) out[`l${lesson.slice(1)}-p${i}`] = fresh[`l${lesson.slice(1)}-p${i}`];
      }
    }
  }

  const before = Object.keys(parsed).length;
  const after = Object.keys(out).length;
  if (after !== before + 16) throw new Error(`expected +16 keys, got ${before} -> ${after}`);
  writeFileSync(FILE, BANNER + JSON.stringify(out, null, 2) + ";\n");
  console.log(`wrote ${FILE}: ${before} -> ${after} entries`);

  // sanity: unchanged keys must be byte-identical in re-stringify
  const re = JSON.parse(readFileSync(FILE, "utf8").slice(start, readFileSync(FILE, "utf8").lastIndexOf("}") + 1));
  for (const key of Object.keys(parsed)) {
    if (JSON.stringify(re[key]) !== JSON.stringify(parsed[key])) throw new Error(`mutated existing key: ${key}`);
  }
  console.log("existing entries byte-identical ✓");
}

main();
